CREATE POLICY workspaces_delete ON public.workspaces AS PERMISSIVE FOR DELETE TO authenticated USING (((auth.uid() = owner_id) OR has_app_role(auth.uid(), 'master'::app_role)));
CREATE POLICY workspaces_insert ON public.workspaces AS PERMISSIVE FOR INSERT TO authenticated WITH CHECK ((auth.uid() = owner_id));
CREATE POLICY workspaces_select ON public.workspaces AS PERMISSIVE FOR SELECT TO authenticated USING ((is_workspace_member(id, auth.uid()) OR has_app_role(auth.uid(), 'master'::app_role)));
CREATE POLICY workspaces_update ON public.workspaces AS PERMISSIVE FOR UPDATE TO authenticated USING ((is_workspace_admin(id, auth.uid()) OR has_app_role(auth.uid(), 'master'::app_role)));
